1	package template
2	
3	import (
4		"fmt"
5		"io"
6		"io/fs"
7		"os"
8		"path/filepath"
9		"strings"
10		"text/template"
11	
12		"github.com/Masterminds/sprig/v3"
13	)
14	
15	const tmplSuffix = ".tmpl"
16	
17	// Render walks srcDir and writes results into destDir. Both path segments and
18	// file contents flow through text/template with sprig helpers. A .tmpl suffix
19	// on a file's basename triggers content rendering and is stripped from the
20	// destination path. Examples:
21	//   - skeleton/README.md.tmpl          → README.md   (contents rendered)
22	//   - skeleton/{{.Name}}/svc.go        → <Name>/svc.go (path rendered, contents copied)
23	//   - skeleton/{{.Name}}.http.tmpl     → <Name>.http (path and contents rendered)
24	//
25	// srcDir is the template's skeleton/ directory; the manifest lives outside
26	// this tree.
27	func Render(srcDir, destDir string, values map[string]any) error {
28		return filepath.WalkDir(srcDir, func(path string, d fs.DirEntry, err error) error {
29			if err != nil {
30				return err
31			}
32			rel, err := filepath.Rel(srcDir, path)
33			if err != nil {
34				return err
35			}
36			if rel == "." {
37				return nil
38			}
39			renderedRel, err := renderPath(rel, values)
40			if err != nil {
41				return err
42			}
43			if renderedRel == "" {
44				return fmt.Errorf("path %q rendered to empty string", rel)
45			}
46			target := filepath.Join(destDir, strings.TrimSuffix(renderedRel, tmplSuffix))
47			if d.IsDir() {
48				return os.MkdirAll(target, 0o755)
49			}
50			info, err := d.Info()
51			if err != nil {
52				return err
53			}
54			if err := os.MkdirAll(filepath.Dir(target), 0o755); err != nil {
55				return err
56			}
57			mode := info.Mode().Perm()
58			if strings.HasSuffix(renderedRel, tmplSuffix) {
59				return renderTemplate(path, target, mode, values)
60			}
61			return copyFile(path, target, mode)
62		})
63	}
64	
65	func renderPath(rel string, values map[string]any) (string, error) {
66		if !strings.Contains(rel, "{{") {
67			return rel, nil
68		}
69		t, err := template.New("path").
70			Funcs(sprig.TxtFuncMap()).
71			Option("missingkey=error").
72			Parse(rel)
73		if err != nil {
74			return "", fmt.Errorf("parse path %q: %w", rel, err)
75		}
76		var buf strings.Builder
77		if err := t.Execute(&buf, values); err != nil {
78			return "", fmt.Errorf("render path %q: %w", rel, err)
79		}
80		return buf.String(), nil
81	}
82	
83	func renderTemplate(src, dst string, mode os.FileMode, values map[string]any) error {
84		raw, err := os.ReadFile(src)
85		if err != nil {
86			return err
87		}
88		t, err := template.New(filepath.Base(src)).
89			Funcs(sprig.TxtFuncMap()).
90			Option("missingkey=error").
91			Parse(string(raw))
92		if err != nil {
93			return fmt.Errorf("parse %s: %w", src, err)
94		}
95		return writeAtomically(dst, mode, func(w io.Writer) error {
96			if err := t.Execute(w, values); err != nil {
97				return fmt.Errorf("render %s: %w", src, err)
98			}
99			return nil
100		})
101	}
102	
103	func copyFile(src, dst string, mode os.FileMode) error {
104		return writeAtomically(dst, mode, func(w io.Writer) error {
105			in, err := os.Open(src)
106			if err != nil {
107				return err
108			}
109			defer in.Close()
110			_, err = io.Copy(w, in)
111			return err
112		})
113	}
114	
115	func writeAtomically(dst string, mode os.FileMode, write func(io.Writer) error) error {
116		dir := filepath.Dir(dst)
117		if err := os.MkdirAll(dir, 0o755); err != nil {
118			return err
119		}
120		tmp, err := os.CreateTemp(dir, "."+filepath.Base(dst)+"-*.tmp")
121		if err != nil {
122			return err
123		}
124		tmpName := tmp.Name()
125		committed := false
126		defer func() {
127			if !committed {
128				_ = os.Remove(tmpName)
129			}
130		}()
131	
132		if err := tmp.Chmod(mode); err != nil {
133			_ = tmp.Close()
134			return err
135		}
136		if err := write(tmp); err != nil {
137			_ = tmp.Close()
138			return err
139		}
140		if err := tmp.Close(); err != nil {
141			return err
142		}
143		if err := os.Rename(tmpName, dst); err != nil {
144			return err
145		}
146		committed = true
147		return nil
148	}
