17	const (
18		// DeployFileName is the repository-level contract, at the root of the
19		// GitOps repository. Its presence is what marks a repository as one this
20		// CLI may deploy through.
21		DeployFileName = "deploy.yaml"
22	
23		// ComponentFileName is the per-component contract, in the component
24		// directory alongside base/ and overlays/.
25		ComponentFileName = "component.yaml"
26	
27		// DomainsDirName is the root of the coordinate tree.
28		DomainsDirName = "domains"
29	
30		// OverlaysDirName holds one directory per environment.
31		OverlaysDirName = "overlays"
32	
33		// SchemaVersion is the newest schema this CLI understands for both files.
34		// Bump only for incompatible changes; new optional fields do not require
35		// a bump.
36		SchemaVersion = 1
37	
38		// SyncAuto and SyncManual are the recognised environment sync policies.
39		// Manual environments are gated in ArgoCD, so deploy commits and pushes
40		// but must not wait for a sync that will never start on its own.
41		SyncAuto   = "auto"
42		SyncManual = "manual"
43	)
