46	type DeployConfig struct {
47		SchemaVersion int    `yaml:"schemaVersion"`
48		Registry      string `yaml:"registry"`
49	
50		// MinimumCliVersion, when set, is the oldest CLI the repository's authors
51		// consider safe to deploy with.
52		MinimumCliVersion string `yaml:"minimumCliVersion"`
53	
54		Argocd       ArgocdConfig                 `yaml:"argocd"`
55		Environments map[string]EnvironmentConfig `yaml:"environments"`
