115	// LoadDeployConfig reads and validates deploy.yaml from the root of a GitOps
116	// repository.
117	func LoadDeployConfig(root string) (*DeployConfig, error) {
118		path := filepath.Join(root, DeployFileName)
119		var cfg DeployConfig
120		if err := decodeFile(path, &cfg); err != nil {
121			if errors.Is(err, fs.ErrNotExist) {
122				return nil, fmt.Errorf("%s has no %s, so it is not a GitOps repository this CLI can deploy through", root, DeployFileName)
123			}
124			return nil, err
125		}
126		if err := cfg.validate(path); err != nil {
127			return nil, err
128		}
129		return &cfg, nil
130	}
