132	func (c *DeployConfig) validate(path string) error {
133		if err := checkSchemaVersion(path, c.SchemaVersion); err != nil {
134			return err
135		}
136		if c.Registry == "" {
137			return fmt.Errorf("%s: registry is required", path)
138		}
139		if len(c.Environments) == 0 {
140			return fmt.Errorf("%s: at least one entry under environments is required", path)
141		}
142		for _, name := range slices.Sorted(maps.Keys(c.Environments)) {
143			env := c.Environments[name]
144			switch env.Sync {
145			case SyncAuto, SyncManual:
146			case "":
147				return fmt.Errorf("%s: environment %q has no sync policy (expected %q or %q)", path, name, SyncAuto, SyncManual)
148			default:
149				return fmt.Errorf("%s: environment %q has sync %q (expected %q or %q)", path, name, env.Sync, SyncAuto, SyncManual)
150			}
151			for _, src := range env.PromotesFrom {
152				if _, ok := c.Environments[src]; !ok {
153					return fmt.Errorf("%s: environment %q promotes from %q, which is not defined", path, name, src)
154				}
155			}
156		}
157		return nil
158	}
