160	// Environment returns the named environment's policy, or an error listing the
161	// environments the repository does define.
162	func (c *DeployConfig) Environment(name string) (EnvironmentConfig, error) {
163		env, ok := c.Environments[name]
164		if !ok {
165			return EnvironmentConfig{}, fmt.Errorf("unknown environment %q; %s defines: %s", name, DeployFileName, strings.Join(c.EnvironmentNames(), ", "))
166		}
167		return env, nil
168	}
169	
170	// EnvironmentNames returns the defined environment names in sorted order.
171	func (c *DeployConfig) EnvironmentNames() []string {
172		return slices.Sorted(maps.Keys(c.Environments))
173	}
174	
175	// PromotionOrder returns the environments in the order changes flow through
176	// them: an environment comes after every environment it promotes from. Ties
177	// break alphabetically, so the order is stable across runs.
178	//
179	// EnvironmentNames sorts alphabetically, which renders the usual three as dev,
180	// prod, staging. That is the wrong story for anything presenting environments
181	// as a pipeline — the promotion graph is what says prod comes last.
182	func (c *DeployConfig) PromotionOrder() []string {
183		// Sources counts the not-yet-emitted environments each one promotes from.
184		// An edge naming an undefined environment is impossible here: validate
185		// rejects the file first.
186		remaining := make(map[string]int, len(c.Environments))
187		for name, env := range c.Environments {
188			sources := 0
189			for _, src := range env.PromotesFrom {
190				// A self-edge is not a dependency on anything else, and counting it
191				// would make the environment permanently unemittable.
192				if src != name {
193					sources++
194				}
195			}
196			remaining[name] = sources
197		}
198	
199		order := make([]string, 0, len(c.Environments))
200		for len(remaining) > 0 {
201			ready := make([]string, 0, len(remaining))
202			for name, sources := range remaining {
203				if sources == 0 {
204					ready = append(ready, name)
205				}
206			}
207	
208			// Nothing is ready, so the remainder is a cycle. deploy.yaml's
209			// validation does not forbid one, and dropping those environments would
210			// hide them from a caller listing what exists — emit them alphabetically
211			// instead.
212			if len(ready) == 0 {
213				order = append(order, slices.Sorted(maps.Keys(remaining))...)
214				break
215			}
216	
217			slices.Sort(ready)
218			order = append(order, ready...)
219			for _, name := range ready {
220				delete(remaining, name)
221			}
222			// Emitting a whole rank at a time keeps siblings adjacent and
223			// alphabetical, rather than interleaving them by discovery order.
224			for _, name := range ready {
225				for other, env := range c.Environments {
226					if _, pending := remaining[other]; !pending {
227						continue
228					}
229					for _, src := range env.PromotesFrom {
230						if src == name {
231							remaining[other]--
232						}
233					}
234				}
235			}
236		}
237		return order
238	}
