240	// LoadComponentConfig reads and validates a component.yaml from a component
241	// directory.
242	func LoadComponentConfig(dir string) (*ComponentConfig, error) {
243		path := filepath.Join(dir, ComponentFileName)
244		var cfg ComponentConfig
245		if err := decodeFile(path, &cfg); err != nil {
246			return nil, err
247		}
248		if err := cfg.validate(path); err != nil {
249			return nil, err
250		}
251		return &cfg, nil
252	}
253	
254	func (c *ComponentConfig) validate(path string) error {
255		if err := checkSchemaVersion(path, c.SchemaVersion); err != nil {
256			return err
257		}
258		if c.Name == "" {
259			return fmt.Errorf("%s: name is required", path)
260		}
261		if len(c.Images) == 0 {
262			return fmt.Errorf("%s: at least one entry under images is required — there is nothing to pin otherwise", path)
263		}
264		for i, img := range c.Images {
265			if img.Name == "" {
266				return fmt.Errorf("%s: images[%d] has no name", path, i)
267			}
268			if hasTagOrDigest(img.Name) {
269				return fmt.Errorf("%s: images[%d] name %q must be a bare repository, without a tag or digest", path, i, img.Name)
270			}
271		}
272		if len(c.Environments) == 0 {
273			return fmt.Errorf("%s: at least one entry under environments is required", path)
274		}
275		return nil
276	}
277	
278	// SupportsEnvironment reports whether the component declares env.
279	func (c *ComponentConfig) SupportsEnvironment(env string) bool {
280		return slices.Contains(c.Environments, env)
281	}
282	
283	// hasTagOrDigest reports whether an image reference carries a tag or digest.
284	//
285	// Only the final path segment is examined, because a colon earlier in the
286	// reference is a registry port: localhost:5555/integrations/app and
287	// harbor.example.com:8443/app are perfectly ordinary repositories, and
288	// rejecting them would rule out every registry not on the default port.
289	func hasTagOrDigest(image string) bool {
290		last := image
291		if i := strings.LastIndex(image, "/"); i >= 0 {
292			last = image[i+1:]
293		}
294		return strings.ContainsAny(last, ":@")
295	}
296	
297	func checkSchemaVersion(path string, got int) error {
298		switch {
299		case got == 0:
300			return fmt.Errorf("%s: schemaVersion is required", path)
301		case got > SchemaVersion:
302			return fmt.Errorf("%s: schemaVersion %d is newer than this CLI supports (%d); upgrade intropy", path, got, SchemaVersion)
303		case got < 1:
304			return fmt.Errorf("%s: schemaVersion %d is not valid", path, got)
305		}
306		return nil
307	}
308	
309	// decodeFile decodes a YAML file, rejecting unknown fields so that a
310	// misspelled key is a loud error rather than a setting that silently does
311	// nothing.
312	func decodeFile(path string, into any) error {
313		f, err := os.Open(path)
314		if err != nil {
315			// Wrapped, so callers can still test for fs.ErrNotExist.
316			return fmt.Errorf("read %s: %w", path, err)
317		}
318		defer f.Close()
319	
320		dec := yaml.NewDecoder(f)
321		dec.KnownFields(true)
322		if err := dec.Decode(into); err != nil {
323			if errors.Is(err, io.EOF) {
324				return fmt.Errorf("parse %s: file is empty", path)
325			}
326			return fmt.Errorf("parse %s: %w", path, err)
327		}
328		return nil
329	}
