package deploy

import (
	"bytes"
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"regexp"
	"slices"
	"strings"
	"text/tabwriter"
)

// PlaceholderPrefix marks a value only a human can supply — a connection string,
// a host, a credential, a cron schedule.
//
// The spelling is load-bearing. It contains no YAML metacharacter, so it is a
// legal unquoted plain scalar in every position including the start of a value;
// it is legal inside a URL; the hint after the prefix says what to supply, so a
// grep hit is self-explanatory; and one regexp finds every instance.
const PlaceholderPrefix = "REPLACE-ME-"

// A hint of at least one character, ending in an alphanumeric so trailing
// punctuation in prose ("set REPLACE-ME-SFTP-HOST, then …") is not swallowed.
var placeholderPattern = regexp.MustCompile(`REPLACE-ME-[A-Z0-9-]*[A-Z0-9]`)

// Placeholder is one unfilled value in one line of one file.
type Placeholder struct {
	// File is relative to the scanned root, slash-separated.
	File string `json:"file"`
	Line int    `json:"line"`

	// Token is the whole marker including its hint, so a reader knows what the
	// value is without opening the file.
	Token string `json:"token"`
}

// scanPlaceholders reports every placeholder in rels, which are slash-separated
// paths relative to root.
//
// A path that does not exist is skipped rather than an error: the same function
// serves --plan, where it scans a staging directory, and a re-run, where it scans
// the committed tree and some of rels were never written.
//
// An unpinned image tag is deliberately *not* a placeholder. Pinning is
// intropy deploy's job, and inviting someone to hand-edit an image tag would
// undo the digest discipline the rest of this package exists to enforce.
func scanPlaceholders(root string, rels []string) ([]Placeholder, error) {
	var out []Placeholder
	for _, rel := range rels {
		data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
		if err != nil {
			if errorsIsNotExist(err) {
				continue
			}
			return nil, fmt.Errorf("scan %s for placeholders: %w", rel, err)
		}
		// A binary file cannot carry a placeholder a human would edit, and
		// reporting a line number in one would be meaningless.
		if bytes.IndexByte(data, 0) >= 0 {
			continue
		}
		for i, line := range strings.Split(string(data), "\n") {
			for _, token := range placeholderPattern.FindAllString(line, -1) {
				out = append(out, Placeholder{File: rel, Line: i + 1, Token: token})
			}
		}
	}

	slices.SortFunc(out, func(a, b Placeholder) int {
		if c := strings.Compare(a.File, b.File); c != 0 {
			return c
		}
		if a.Line != b.Line {
			return a.Line - b.Line
		}
		return strings.Compare(a.Token, b.Token)
	})
	return out, nil
}

func errorsIsNotExist(err error) bool {
	return os.IsNotExist(err) || err == fs.ErrNotExist
}

// reportPlaceholders writes the placeholder table and the summary line.
//
// Remaining placeholders are the expected outcome, never a failure: complete
// manifests are explicitly not the goal, and the command's value is that the
// remaining work is now a bounded, greppable list.
func reportPlaceholders(out output, found []Placeholder) {
	if len(found) == 0 {
		fmt.Fprintln(out.Stdout, "\nno placeholders left to fill in")
		return
	}

	fmt.Fprintf(out.Stdout, "\n%s\n", summarisePlaceholders(found))
	tw := tabwriter.NewWriter(out.Stdout, 0, 0, 2, ' ', 0)
	for _, p := range found {
		fmt.Fprintf(tw, "  %s:%d\t%s\n", p.File, p.Line, p.Token)
	}
	_ = tw.Flush()
	fmt.Fprintf(out.Stdout, "\nImage tags are not in this list: intropy deploy pins digests, so leave them alone.\n")
}

func summarisePlaceholders(found []Placeholder) string {
	files := map[string]bool{}
	for _, p := range found {
		files[p.File] = true
	}
	return fmt.Sprintf("%d placeholder%s to fill in across %d file%s:",
		len(found), plural(len(found)), len(files), plural(len(files)))
}

func plural(n int) string {
	if n == 1 {
		return ""
	}
	return "s"
}

package deploy

import (
	"bytes"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeScanFile(t *testing.T, root, rel, content string) {
	t.Helper()
	path := filepath.Join(root, filepath.FromSlash(rel))
	if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func TestScanPlaceholdersReportsFileAndLine(t *testing.T) {
	root := t.TempDir()
	writeScanFile(t, root, "host/base/secrets/secrets.yaml", `apiVersion: v1
kind: Secret
stringData:
  connection: REPLACE-ME-RABBITMQ-CONNECTION-STRING
  host: REPLACE-ME-SFTP-HOST
`)

	found, err := scanPlaceholders(root, []string{"host/base/secrets/secrets.yaml"})
	if err != nil {
		t.Fatal(err)
	}
	if len(found) != 2 {
		t.Fatalf("found = %+v, want 2", found)
	}
	if found[0].Line != 4 || found[0].Token != "REPLACE-ME-RABBITMQ-CONNECTION-STRING" {
		t.Errorf("found[0] = %+v", found[0])
	}
	if found[1].Line != 5 || found[1].Token != "REPLACE-ME-SFTP-HOST" {
		t.Errorf("found[1] = %+v", found[1])
	}
	if found[0].File != "host/base/secrets/secrets.yaml" {
		t.Errorf("File = %q, want a slash-separated relative path", found[0].File)
	}
}

// Pinning is intropy deploy's job. Reporting the tag here would invite someone
// to hand-edit it, which is exactly the discipline this package enforces.
func TestScanPlaceholdersIgnoresUnpinnedImageTag(t *testing.T) {
	root := t.TempDir()
	writeScanFile(t, root, "base/deployment.yaml", `spec:
  containers:
    - image: harbor.intropy.io/fluxia/order-extract:unpinned
`)

	found, err := scanPlaceholders(root, []string{"base/deployment.yaml"})
	if err != nil {
		t.Fatal(err)
	}
	if len(found) != 0 {
		t.Errorf("found = %+v, want none", found)
	}
}

func TestScanPlaceholdersFindsSeveralOnOneLine(t *testing.T) {
	root := t.TempDir()
	writeScanFile(t, root, "a.yaml", "url: sftp://REPLACE-ME-SFTP-USER@REPLACE-ME-SFTP-HOST/in\n")

	found, err := scanPlaceholders(root, []string{"a.yaml"})
	if err != nil {
		t.Fatal(err)
	}
	if len(found) != 2 {
		t.Fatalf("found = %+v, want 2", found)
	}
	// Sorted by token within a line, so output is stable.
	if found[0].Token != "REPLACE-ME-SFTP-HOST" || found[1].Token != "REPLACE-ME-SFTP-USER" {
		t.Errorf("tokens = %q, %q", found[0].Token, found[1].Token)
	}
}

// The README the template renders explains each placeholder, so it must be
// scanned too rather than only the YAML.
func TestScanPlaceholdersCoversMarkdown(t *testing.T) {
	root := t.TempDir()
	writeScanFile(t, root, "README.md", "Set `REPLACE-ME-KEYVAULT-URL` to the vault endpoint.\n")

	found, err := scanPlaceholders(root, []string{"README.md"})
	if err != nil {
		t.Fatal(err)
	}
	if len(found) != 1 || found[0].Token != "REPLACE-ME-KEYVAULT-URL" {
		t.Fatalf("found = %+v", found)
	}
}

// Trailing prose punctuation must not become part of the token, or the reported
// value would not match what is in the file.
func TestScanPlaceholdersStopsAtPunctuation(t *testing.T) {
	root := t.TempDir()
	writeScanFile(t, root, "a.md", "set REPLACE-ME-SFTP-HOST, then restart\n")

	found, err := scanPlaceholders(root, []string{"a.md"})
	if err != nil {
		t.Fatal(err)
	}
	if len(found) != 1 || found[0].Token != "REPLACE-ME-SFTP-HOST" {
		t.Fatalf("found = %+v", found)
	}
}

func TestScanPlaceholdersSkipsBinaryFiles(t *testing.T) {
	root := t.TempDir()
	path := filepath.Join(root, "blob.bin")
	if err := os.WriteFile(path, []byte("REPLACE-ME-X\x00\x01\x02"), 0o644); err != nil {
		t.Fatal(err)
	}

	found, err := scanPlaceholders(root, []string{"blob.bin"})
	if err != nil {
		t.Fatal(err)
	}
	if len(found) != 0 {
		t.Errorf("found = %+v, want none in a binary file", found)
	}
}

// A re-run scans the committed tree, where a file classified skip-exists is
// present but one that was never written is not.
func TestScanPlaceholdersSkipsMissingFiles(t *testing.T) {
	root := t.TempDir()
	writeScanFile(t, root, "present.yaml", "x: REPLACE-ME-A\n")

	found, err := scanPlaceholders(root, []string{"absent.yaml", "present.yaml"})
	if err != nil {
		t.Fatalf("a missing path must not be an error: %v", err)
	}
	if len(found) != 1 || found[0].File != "present.yaml" {
		t.Fatalf("found = %+v", found)
	}
}

func TestScanPlaceholdersIsSortedAcrossFiles(t *testing.T) {
	root := t.TempDir()
	writeScanFile(t, root, "z.yaml", "a: REPLACE-ME-Z\n")
	writeScanFile(t, root, "a.yaml", "a: REPLACE-ME-A\n")

	found, err := scanPlaceholders(root, []string{"z.yaml", "a.yaml"})
	if err != nil {
		t.Fatal(err)
	}
	if len(found) != 2 || found[0].File != "a.yaml" || found[1].File != "z.yaml" {
		t.Errorf("found = %+v, want them sorted by file", found)
	}
}

func TestReportPlaceholdersSaysImagesAreNotIncluded(t *testing.T) {
	var stdout bytes.Buffer
	out := output{Stdout: &stdout, Format: OutputPlain}

	reportPlaceholders(out, []Placeholder{
		{File: "host/base/secrets/secrets.yaml", Line: 4, Token: "REPLACE-ME-RABBITMQ-CONNECTION-STRING"},
	})

