package deploy

import (
	"fmt"
	"io/fs"
	"os"
	"path"
	"path/filepath"
	"slices"
	"strings"

	"github.com/integrio-intropy/intropy-cli/internal/gitops"
	"github.com/integrio-intropy/intropy-cli/internal/kustomize"
)

// What scaffolding does to one file.
const (
	// ActionCreate: the file is not in the repository yet.
	ActionCreate = "create"

	// ActionIdentical: already there, byte for byte. Not written, and not
	// counted as a change — this is what makes a re-run a genuine no-op.
	ActionIdentical = "identical"

	// ActionSkipExists: already there and different. Left alone, because a
	// human or a previous deploy owns it now. Reported so the difference is
	// visible rather than silently ignored.
	ActionSkipExists = "skip-exists"

	// ActionOverwrite: already there and different, and --force was given.
	ActionOverwrite = "overwrite"
)

// FileAction is one staged file's fate.
type FileAction struct {
	// Rel is relative to the repository root, slash-separated.
	Rel    string `json:"path"`
	Action string `json:"action"`
}

// Writes reports whether the action puts bytes on disk.
func (a FileAction) Writes() bool {
	return a.Action == ActionCreate || a.Action == ActionOverwrite
}

// stageRels lists every file a render produced, relative to the staging root and
// slash-separated, sorted so a plan reads in tree order.
func stageRels(stagingDir string) ([]string, error) {
	var rels []string
	err := filepath.WalkDir(stagingDir, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		if d.IsDir() {
			return nil
		}
		rel, err := filepath.Rel(stagingDir, p)
		if err != nil {
			return err
		}
		rels = append(rels, filepath.ToSlash(rel))
		return nil
	})
	if err != nil {
		return nil, fmt.Errorf("read staged manifests: %w", err)
	}
	slices.Sort(rels)
	return rels, nil
}

// classifyStaged decides what to do with each staged file, given what is already
// in the repository.
//
// Rendering straight into the tree is never an option: the renderer overwrites,
// and an overlay holds digests intropy deploy pinned. Staging first and
// classifying second is what makes this command additive — a system gains a
// component and only that subtree is new, while everything a human has since
// edited is left exactly as it is.
func classifyStaged(stagingDir, destRoot string, rels []string, force bool) ([]FileAction, error) {
	actions := make([]FileAction, 0, len(rels))
	for _, rel := range rels {
		staged := filepath.Join(stagingDir, filepath.FromSlash(rel))
		existing := filepath.Join(destRoot, filepath.FromSlash(rel))

		current, err := os.ReadFile(existing)
		if err != nil {
			if !os.IsNotExist(err) {
				return nil, fmt.Errorf("read %s: %w", rel, err)
			}
			actions = append(actions, FileAction{Rel: rel, Action: ActionCreate})
			continue
		}
		next, err := os.ReadFile(staged)
		if err != nil {
			return nil, fmt.Errorf("read staged %s: %w", rel, err)
		}

		switch {
		case string(current) == string(next):
			actions = append(actions, FileAction{Rel: rel, Action: ActionIdentical})
		case force:
			actions = append(actions, FileAction{Rel: rel, Action: ActionOverwrite})
		default:
			actions = append(actions, FileAction{Rel: rel, Action: ActionSkipExists})
		}
	}
	return actions, nil
}

// assertForceIsSafe refuses a --force that would overwrite a pinned overlay.
//
// kustomize records a digest in the overlay's kustomization file, so replacing
// one with a freshly rendered skeleton un-deploys whatever that environment is
// running. There is no version of that a user meant to ask for, so this is a
// hard refusal rather than a warning, and it names every file so the fix is
// obvious.
func assertForceIsSafe(destRoot string, actions []FileAction) error {
	var pinned []string
	for _, a := range actions {
		if a.Action != ActionOverwrite || !isKustomizationFile(a.Rel) {
			continue
		}
		k, _, err := kustomize.ReadKustomization(filepath.Join(destRoot, filepath.FromSlash(path.Dir(a.Rel))))
		if err != nil {
			// Unreadable or absent: nothing to protect, and the render will
			// report a real problem if there is one.
			continue
		}
		for _, img := range k.Images {
			if img.Digest != "" {
				pinned = append(pinned, fmt.Sprintf("  %s pins %s at %s", a.Rel, img.Name, img.Digest))
				break
			}
		}
	}
	if len(pinned) == 0 {
		return nil
	}
	return fmt.Errorf("--force would overwrite %d overlay%s that pin a digest, un-deploying what they run:\n%s\n\nRemove those paths from the scaffold, or delete the overlay deliberately first.",
		len(pinned), plural(len(pinned)), strings.Join(pinned, "\n"))
}

func isKustomizationFile(rel string) bool {
	return slices.Contains(kustomize.KustomizationFileNames, path.Base(rel))
}

// applyStaged copies the staged files the actions say to write.
//
// Nothing is written until every action has been classified, so a failure part
// way through classification leaves the repository untouched.
func applyStaged(stagingDir, destRoot string, actions []FileAction) ([]string, error) {
	var written []string
	for _, a := range actions {
		if !a.Writes() {
			continue
		}
		src := filepath.Join(stagingDir, filepath.FromSlash(a.Rel))
		dst := filepath.Join(destRoot, filepath.FromSlash(a.Rel))
		if err := os.MkdirAll(filepath.Dir(dst), 0o755); err != nil {
			return written, fmt.Errorf("create %s: %w", path.Dir(a.Rel), err)
		}
		data, err := os.ReadFile(src)
		if err != nil {
			return written, fmt.Errorf("read staged %s: %w", a.Rel, err)
		}
		if err := os.WriteFile(dst, data, 0o644); err != nil {
			return written, fmt.Errorf("write %s: %w", a.Rel, err)
		}
		written = append(written, a.Rel)
	}
	return written, nil
}

// componentRelPath is the repository-relative directory a component's manifests
// live in, slash-separated.
func componentRelPath(domain, system, component string) string {
	return gitops.Coordinate{Domain: domain, System: system, Component: component}.RelPath()
}

// summariseActions counts the actions by kind for the one-line report.
func summariseActions(actions []FileAction) string {
	counts := map[string]int{}
	for _, a := range actions {
		counts[a.Action]++
	}
	var parts []string
	for _, kind := range []string{ActionCreate, ActionOverwrite, ActionSkipExists, ActionIdentical} {
		if n := counts[kind]; n > 0 {
			parts = append(parts, fmt.Sprintf("%d %s", n, kind))
		}
	}
	if len(parts) == 0 {
		return "nothing to do"
	}
	return strings.Join(parts, ", ")
}

package deploy

import (
	"os"
	"path/filepath"
	"strings"
	"testing"
)

func writeTree(t *testing.T, root string, files map[string]string) {
	t.Helper()
	for rel, content := range files {
		path := filepath.Join(root, filepath.FromSlash(rel))
		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
			t.Fatal(err)
		}
	}
}

func actionFor(t *testing.T, actions []FileAction, rel string) string {
	t.Helper()
	for _, a := range actions {
		if a.Rel == rel {
			return a.Action
		}
	}
	t.Fatalf("no action for %q in %+v", rel, actions)
	return ""
}

func classify(t *testing.T, staging, dest string, force bool) []FileAction {
	t.Helper()
	rels, err := stageRels(staging)
	if err != nil {
		t.Fatal(err)
	}
	actions, err := classifyStaged(staging, dest, rels, force)
	if err != nil {
		t.Fatal(err)
	}
	return actions
}

func TestStageRelsIsSortedAndSlashSeparated(t *testing.T) {
	staging := t.TempDir()
	writeTree(t, staging, map[string]string{
		"host/overlays/dev/kustomization.yaml": "dev\n",
		"host/base/kustomization.yaml":         "base\n",
		"host/component.yaml":                  "comp\n",
	})

	rels, err := stageRels(staging)
	if err != nil {
		t.Fatal(err)
	}
	want := []string{
		"host/base/kustomization.yaml",
		"host/component.yaml",
		"host/overlays/dev/kustomization.yaml",
	}
	if strings.Join(rels, "|") != strings.Join(want, "|") {
		t.Errorf("rels = %v, want %v", rels, want)
	}
}

func TestClassifyFreshOnboardingIsAllCreate(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{
		"host/component.yaml":          "kind: shared\n",
		"host/base/kustomization.yaml": "resources: []\n",
	})

	for _, a := range classify(t, staging, dest, false) {
		if a.Action != ActionCreate {
			t.Errorf("%s = %q, want create", a.Rel, a.Action)
		}
	}
}

// A re-run must be a genuine no-op, not a stream of overwrites that churn the
// git history.
func TestClassifyIdenticalFileIsNotAChange(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{"host/component.yaml": "kind: shared\n"})
	writeTree(t, dest, map[string]string{"host/component.yaml": "kind: shared\n"})

	actions := classify(t, staging, dest, false)
	if got := actionFor(t, actions, "host/component.yaml"); got != ActionIdentical {
		t.Errorf("action = %q, want identical", got)
	}
	for _, a := range actions {
		if a.Writes() {
			t.Errorf("%s would be written", a.Rel)
		}
	}
}

func TestClassifyDifferingFileIsSkipped(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{"host/component.yaml": "kind: shared\n"})
	writeTree(t, dest, map[string]string{"host/component.yaml": "kind: shared\n# hand-edited\n"})

	if got := actionFor(t, classify(t, staging, dest, false), "host/component.yaml"); got != ActionSkipExists {
		t.Errorf("action = %q, want skip-exists", got)
	}
}

func TestClassifyDifferingFileWithForceIsOverwrite(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{"host/component.yaml": "new\n"})
	writeTree(t, dest, map[string]string{"host/component.yaml": "old\n"})

	if got := actionFor(t, classify(t, staging, dest, true), "host/component.yaml"); got != ActionOverwrite {
		t.Errorf("action = %q, want overwrite", got)
	}
}

// The property that makes this safe to re-run for a system's whole life: a new
// component is created and every existing one is left alone.
func TestClassifyIsAdditiveWhenTheTopologyGrows(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{
		"order-extract/component.yaml": "existing\n",
		"order-load/component.yaml":    "brand new\n",
	})
	writeTree(t, dest, map[string]string{
		"order-extract/component.yaml": "existing\n",
	})

	actions := classify(t, staging, dest, false)
	if got := actionFor(t, actions, "order-extract/component.yaml"); got != ActionIdentical {
		t.Errorf("existing component = %q, want identical", got)
	}
	if got := actionFor(t, actions, "order-load/component.yaml"); got != ActionCreate {
		t.Errorf("new component = %q, want create", got)
	}
}

func TestApplyStagedWritesOnlyWhatTheActionsSay(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{
		"a/component.yaml": "created\n",
		"b/component.yaml": "not written\n",
	})
	writeTree(t, dest, map[string]string{"b/component.yaml": "left alone\n"})

	actions := classify(t, staging, dest, false)
	written, err := applyStaged(staging, dest, actions)
	if err != nil {
		t.Fatal(err)
	}
	if len(written) != 1 || written[0] != "a/component.yaml" {
		t.Fatalf("written = %v", written)
	}
	if got := readTreeFile(t, dest, "a/component.yaml"); got != "created\n" {
		t.Errorf("a = %q", got)
	}
	if got := readTreeFile(t, dest, "b/component.yaml"); got != "left alone\n" {
		t.Errorf("b = %q, want it untouched", got)
	}
}

// Overwriting an overlay that pins a digest un-deploys what it runs, and no user
// means to ask for that.
func TestForceIsRefusedOnAPinnedOverlay(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{
		"order-extract/overlays/dev/kustomization.yaml": "resources:\n  - ../../base\n",
	})
	writeTree(t, dest, map[string]string{
		"order-extract/overlays/dev/kustomization.yaml": `resources:
  - ../../base
images:
  - name: harbor.intropy.io/fluxia/order-extract
    digest: sha256:c0ffee
`,
	})

	actions := classify(t, staging, dest, true)
	err := assertForceIsSafe(dest, actions)
	if err == nil {
		t.Fatal("expected --force to be refused")
	}
	for _, want := range []string{"order-extract/overlays/dev/kustomization.yaml", "sha256:c0ffee"} {
		if !strings.Contains(err.Error(), want) {
			t.Errorf("error does not name %q: %v", want, err)
		}
	}
}

func TestForceIsAllowedOnAnUnpinnedOverlay(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{
		"order-extract/overlays/dev/kustomization.yaml": "resources:\n  - ../../base\n",
	})
	writeTree(t, dest, map[string]string{
		"order-extract/overlays/dev/kustomization.yaml": "resources:\n  - ../../base\nnamespace: integrations\n",
	})

	if err := assertForceIsSafe(dest, classify(t, staging, dest, true)); err != nil {
		t.Errorf("an unpinned overlay should be overwritable: %v", err)
	}
}

// Without --force nothing is overwritten, so a pinned overlay needs no guard.
func TestForceGuardIgnoresSkippedFiles(t *testing.T) {
	staging, dest := t.TempDir(), t.TempDir()
	writeTree(t, staging, map[string]string{
		"order-extract/overlays/dev/kustomization.yaml": "resources: []\n",
	})
	writeTree(t, dest, map[string]string{
		"order-extract/overlays/dev/kustomization.yaml": "images:\n  - name: x\n    digest: sha256:c0ffee\n",
	})

	if err := assertForceIsSafe(dest, classify(t, staging, dest, false)); err != nil {
		t.Errorf("no overwrite means no guard: %v", err)
	}
}

func TestSummariseActions(t *testing.T) {
	got := summariseActions([]FileAction{
		{Rel: "a", Action: ActionCreate},
		{Rel: "b", Action: ActionCreate},
		{Rel: "c", Action: ActionIdentical},
		{Rel: "d", Action: ActionSkipExists},
	})
	if got != "2 create, 1 skip-exists, 1 identical" {
		t.Errorf("summary = %q", got)
	}
	if got := summariseActions(nil); got != "nothing to do" {
		t.Errorf("empty summary = %q", got)
	}
}

func TestComponentRelPathIsSlashSeparated(t *testing.T) {
	if got := componentRelPath("sales", "ordersync", "host"); got != "domains/sales/ordersync/host" {
		t.Errorf("componentRelPath = %q", got)
	}
}

func readTreeFile(t *testing.T, root, rel string) string {
	t.Helper()
	data, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel)))
	if err != nil {
		t.Fatal(err)
	}
	return string(data)
}

